window.labTexts = {"1":{"title":"1-тақырып бойынша бақылау сұрақтары","filePath":"задание/1-лаб.docx","html":"<h3><strong>1-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p> Азаматтық құқық дегеніміз не және оның құқық салалары жүйесіндегі </p><p> орны қандай?</p></li><li><p>Азаматтық құқықтың пәнін қандай қоғамдық қатынастар құрайды? Мысалдар келтіріңіз.</p></li><li><p>Азаматтық-құқықтық реттеу әдісінің мәні неде? Ол басқа құық салаларының әдістерінен несімен ерекшеленеді?</p></li><li><p>Азаматтық-құқықтық реттеу әдісінің жалпы сипаттамасы қандай?</p></li><li><p>Диспозитивтік әдістің мәні неде және ол қандай жағдайларда қолданылады?</p></li><li><p>Императивтік әдіс азаматтық құқықта қай кезде қолданылады және оның ерекшелігі неде?</p></li><li><p>Азаматтық қатынастарға қатысушылардың теңдігі қағидасының құқықтық мазмұны неде?</p></li><li><p>Меншікке қол сұқпаушылық қағидасы азамттық құқықта қалай жүзеге асырылады?</p></li><li><p>Шарт еркіндігі қағидасы нені білдіреді және оның шектеулері қандай жағдайларда қолданылады?</p></li><li><p> Жеке істерге өз бетінше араласуға жол бермеу қағидасының мәні қандай?</p></li></ol>"},"2":{"title":"2-тақырып бойынша бақылау сұрақтары","filePath":"задание/2-лаб.docx","html":"<h3>2-тақырып бойынша бақылау сұрақтары</h3><ol><li><p>Құқықтың қайнар көздері дегеніміз не?</p></li><li><p>Азаматтық құқықтың халықаралық қайнар көздеріне не жатады?</p></li><li><p>Азаматтық құқықтың қосалқы қайнар көзіне не кіреді және неге?</p></li><li><p>Азаматтық құқық нормативтік актілерінің иерархиясын көрсетіңіз?</p></li><li><p>ҚР Азаматтық кодексінің басқа заңдардан айырмашылығы неде? Оның құрылымы қандай?</p></li><li><p>Азаматтық құқық актілері қашан күшіне енеді?</p></li><li><p>Нормативтік актілердің әрекеті қашан тоқтайды?</p></li><li><p>Азаматтық құқық актілерінің кері күші бар ма?</p></li><li><p>Нормативтік актілер қай аумақта қолданылады?</p></li><li><p> Нормативтік актілер қандай тұлғаларға таралады?</p></li></ol>"},"3":{"title":"3-тақырып бойынша бақылау сұрақтары","filePath":"задание/3-лаб.docx","html":"<h3><strong>3-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Азаматтық-құқықтық қатынастар дегеніміз не? Олардың құқықтық мәнін ашыңыз. </p></li><li><p>Азаматтық-құқықтық қатынастардың реттелу пәні қандай қоғамдық қатынастарды қамтиды?</p></li><li><p>Азаматтық-құқықты реттеудің диспозитивтік тәсілі нені білдіреді?</p></li><li><p>Азаматтық-құқықтық қатынастардың құрылымдық элементтерін атаңыз және қысқаша сипаттаңыз. </p></li><li><p>Азаматтық-құқықтық қатынастардың субъектілері кімдер болып табылады?</p></li><li><p>Азаматтық-құқықтық қатынастардың объектісі ұғымына анықтама беріңіз. </p></li><li><p>Азаматтық-құқықтық қатынастардың мазмұны неден тұрады?</p></li><li><p>Мүліктік және жеке мүліктік емес қатынастардың айырмашылығы неде?</p></li><li><p>Абсолюттік және салыстырмалы азаматтық-құқықтық қатынастарға мысал келтіріңіз. </p></li><li><p> Азаматтық-құқықтық қатынастардың пайда болуына қандай заңды фактілер негіз болады?</p></li></ol>"},"4":{"title":"4-тақырып бойынша бақылау сұрақтары","filePath":"задание/4-лаб.docx","html":"<h3><strong>4-тақырып бойынша бақылау </strong><strong>сұрақтары </strong></h3><ol><li><p>Азаматтық құқықтағы әрекет қабілеттілік ұғымының мазмұны мен құқықтық маңызын ашып көрсетіңіз. </p></li><li><p>Он төрт жасқа дейінгі кәмелетке толмағандардың әрекет қабілеттілігінің ерекшеліктері қандай?</p></li><li><p>Он төрт жастан он сегіз жасқа дейінгі тұлғалардың ішінара әрекет қабілеттілігі қандай құқықтарды қамтиды?</p></li><li><p>Кәмелетке толмағандардың өз табысына дербес билік ету құқығы қандай заңдық негіздерге сүйенеді?</p></li><li><p>Әрекет қабілеттілікті шектеудің азаматтық-құқықтық мәні неде және ол қандай жағдайларда қолданылады?</p></li><li><p>Әрекет қабілеттілігі шектеулі тұлғаның мәмілелер жасау тәртібін сипаттаңыз. </p></li><li><p>Психикалық жағдайға байланысты әрекетке қабілетсіз деп танудың соттық тәртібінің маңызын ашыңыз. </p></li><li><p>Хабар-ошарсыз кетті деп танудың азаматтық құқықтық салдары қандай?</p></li><li><p>Тұлғаны өлді деп жариялаудың негіздері мен құқықтық салдарын сипаттаңыз</p></li><li><p> Өлді деп жарияланған тұлға тірі оралған жағдайда қандай азаматтық-құқықтық салдарлар туындайды?</p></li></ol>"},"5":{"title":"5-тақырып бойынша бақылау сұрақтары","filePath":"задание/5-лаб.docx","html":"<h3><strong>5-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Азаматтық құқықтағы заңды тұлға ұғымының мәнін түсіндіріңіз. </p></li><li><p>ҚР Азаматтық кодексі бойынша заңды тұлғаның негізгі белгілерін атаңыз. </p></li><li><p>Ұйымдастырушылық бірлік белгісі нені білдіреді?</p></li><li><p>Заңды тұлғаның оқшауланған мүлкі дегеніміз не және оның маңызы қандай?</p></li><li><p>Заңды тұлғаның өз міндеттемелері бойынша дербес жауапкершілігі қалай түсіндіріледі?</p></li><li><p>Заңды тұлғаның құқық қабілеттілігі қашан пайда болады және қашан тоқтатылады?</p></li><li><p>Заңды тұлға азаматтық құқықтарды және міндеттерді қалай жүзеге </p><p> асырады?</p></li><li><p>Заңды тұлға органдарының құқықтық маңызы қандай?</p></li><li><p>Коммерциялық және коммерциялық емес ұйымдардың </p><p> айырмашылықтарын сипаттаңыз. </p></li><li><p> Филиал мен өкілдіктің ұқсастығы мен айырмашылығы қандай?</p></li></ol>"},"6":{"title":"6-тақырып бойынша бақылау сұрақтары","filePath":"задание/6-лаб.docx","html":"<h3><strong>6-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Азаматтық-құқықтық қатынастарда тараптардың теңдігі қандай қағидалармен көрініс табады? </p></li><li><p>Коммерциялық ұйым дегеніміз не және оның коммерциялық емес ұйымнан басты айырмашылығы қандай?</p></li><li><p>ҚР АК 33-бабындағы заңды тұлғаның анықтамасын түсіндіріңіз. </p></li><li><p>Неліктен ұйым мемлекеттік тіркеуден өтпесе заңды тұлға болып саналмайды?</p></li><li><p>Коммерциялық ұйымдардың жалпы ортақ белгілерін атаңыз (кемінде 4 белгі ). </p></li><li><p>Мемлекеттік кәсіпорын дегеніміз не, оның мүлкіне меншік құқығы кімге тиесілі?</p></li><li><p>Мемлекеттік кәсіпорынның «шаруашылық жүргізу құқығы» мен «жедел басқару құқығы» ерекшелігін түсіндіріңіз.</p></li><li><p> Шаруашылық серіктестік дегеніміз не және не үшін Қазақстанда кең таралған?</p></li><li><p>ЖШС-тің ерекшелігі неде, қатысушылардың тәуекелі қалай шектеледі?</p></li><li><p>Өндірістік кооперативтің серіктестіктен айырмашылығы қандай және оның негізгі белгісі не?</p></li></ol>"},"7":{"title":"7-тақырып бойынша бақылау сұрақтары","filePath":"задание/7-лаб.docx","html":"<h3><strong>7-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Коммерциялық емес ұйымның коммерциялық ұйымнан айырмашылығы қандай?</p></li><li><p>Коммерциялық емес ұйым қандай мақсаттар үшін құрылады?</p></li><li><p>Коммерциялық емес ұйым табыс тапса, ол табыс қалай жұмсалады?</p></li><li><p>Ұйымның азаматтық құқық субъектілігі қай уақытта пайда болады?</p></li><li><p>Арнайы құқық қабілеттілік ұғымын түсіндіріңіз.</p></li><li><p>Коммерциялық емес ұйым жарғылық мақсаттан тыс әрекет етсе қандай қауіп туындайды?</p></li><li><p>Коммерциялық емес ұйымдардың негізгі түрлерін атаңыз.</p></li><li><p>Қоғамдық бірлестік пен қордың айырмашылығы неде?</p></li><li><p>Коммерциялық емес ұйым өз міндеттемелері үшін қалай жауап береді?</p></li><li><p>Коммерциялық емес ұйымның таратылуы кезінде мүлік қалай бөлінеді?</p></li></ol>"},"8":{"title":"8-тақырып бойынша бақылау сұрақтары","filePath":"задание/8-лаб.docx","html":"<h3><strong>8-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Азаматтық құқық объектісі дегеніміз не?</p></li><li><p>Азаматтық құқық объектілерін дұрыс анықтаудың азаматтық айналымдағы маңызы неде?</p></li><li><p>ҚР Азаматтық кодексі бойынша азаматтық құқық объектілеріне қандай игіліктер мен құқықтар жатады?</p></li><li><p>Зат ұғымына қандай мүліктер кіреді және ол қандай объект түрі болып саналады?</p></li><li><p>Мүліктік құқықтар дегеніміз не және оларға мысал келтіріңіз.</p></li><li><p>Жұмыс пен қызметтің айырмашылығын түсіндіріңіз.</p></li><li><p>Жұмыс не қызмет объект болғанда шартта қандай негізгі талаптар көрсетілуі тиіс?</p></li><li><p>Ақпарат азаматтық құқық объектісі ретінде қалай қорғалады (негізгі бағыттарымен)?</p></li><li><p>Интеллектуалдық меншік объектілеріне не жатады?</p></li><li><p> Азаматтық құқық объектілерінің айналым қабілеттілігі нені білдіреді және ол қандай топтарға бөлінеді?</p></li></ol>"},"9":{"title":"9-тақырып бойынша бақылау сұрақтары","filePath":"задание/9-лаб.docx","html":"<h3><strong>9-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Азаматтық құқық объектілері дегеніміз не?</p></li><li><p>Бағалы қағаздардың негізгі белгілерін атаңыз.</p></li><li><p>Акция мен облигацияның айырмашылығы неде?</p></li><li><p>Мүліктік құқықтардың мәні қандай?</p></li><li><p>Цессия дегеніміз не?</p></li><li><p>Қандай құқықтар айналымға жатпайды?</p></li><li><p>Материалдық емес игіліктердің ерекшелігі неде?</p></li><li><p>Ар-намыс пен қадір-қасиет қалай қорғалады?</p></li><li><p>Электрондық бағалы қағаздардың артықшылығы қандай?</p></li><li><p>Азаматтық құқық объектілерін дұрыс анықтаудың маңызы неде?</p></li></ol>"},"10":{"title":"10-тақырып бойынша бақылау сұрақтары","filePath":"задание/10-лаб.docx","html":"<h3><strong>10-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Мәміле дегеніміз не?</p></li><li><p>Мәміленің азаматтық құқықтағы маңызы қандай?</p></li><li><p>Мәміленің негізгі белгілерін атаңыз.</p></li><li><p>Мәмілелер тараптар санына қарай қалай бөлінеді?</p></li><li><p>Өтемді және өтемсіз мәміленің айырмашылығы неде?</p></li><li><p>Консенсуалды және нақты мәмілелер дегеніміз не?</p></li><li><p>Мәміленің қандай нысандары бар?</p></li><li><p>Мәміленің жарамдылық шарттарын атаңыз.</p></li><li><p>Жарамсыз мәміле дегеніміз не?</p></li><li><p>Реституцияның мәні мен маңызы қандай?</p></li></ol>"},"11":{"title":"11-тақырып бойынша бақылау сұрақтары","filePath":"задание/11-лаб.docx","html":"<h3><strong>11-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Өкілдік дееніміз не?</p></li><li><p>Өкілдік беруші мен өкілдің айырмашылығы қандай?</p></li><li><p>Өкілдіктің азаматтық құқықтағы маңызы неде?</p></li><li><p>Заңды өкілдік дегеніміз не?</p></li><li><p>Шарттық өкілдік қалай жүзеге асырылады?</p></li><li><p>Әкімшілік өкілдікке қандай мысалдар келтіруге болады?</p></li><li><p>Сенімхат дегеніміз не?</p></li><li><p>Сенімхаттың міндетті реквизиттері қандай?</p></li><li><p>Сенімхат қандай жағдайда тоқтатылады?</p></li><li><p>Өкілдің негізгі міндеттері қандай?</p></li></ol>"},"12":{"title":"12-тақырып бойынша бақылау сұрақтары","filePath":"задание/12-лаб.docx","html":"<h3><strong>12-тақырып бойынша бақылау сұрақтары</strong> </h3><ol><li><p>Азаматтық құқықтағы мерзімдердің ұғымын түсіндіріңіз.</p></li><li><p>Мерзімдердің азаматтық айналымдағы маңызы неде?</p></li><li><p>Мерзімдер қандай негіздер бойынша жіктеледі?</p></li><li><p>Күнтізбелік күнмен белгіленетін мерзімдерге мысал келтіріңіз.</p></li><li><p>Оқиғамен байланысты мерзімдер қалай есептеледі?</p></li><li><p>Құқықты жүзеге асыру мерзімдері мен міндеттемені орындау мерзімдерінің айырмашылығы қандай?</p></li><li><p>Мерзімдерді есептеудің жалпы ережелерін атаңыз.</p></li><li><p>Талап қою мерзімінің ұғымы мен мақсаты қандай?</p></li><li><p>Жалпы және арнайы талап қою мерзімдерінің айырмашылығын түсіндіріңіз.</p></li><li><p>Талап қою мерзімінің өтуінің құқықтық салдары қандай?</p></li></ol>"},"13":{"title":"13-тақырып бойынша бақылау сұрақтары","filePath":"задание/13-лаб.docx","html":"<h3><strong>13-тақырып бойынша бақылау сұрақтары</strong> </h3><ol><li><p>Меншік құқығы дегеніміз не?</p></li><li><p>Меншік құқығының азаматтық құқықтағы орны қандай?</p></li><li><p>Меншік қатынастарының тарихи даму кезеңдерін атаңыз.</p></li><li><p>Қазақстан Республикасының Конституциясында меншік құқығы қалай қорғалған?</p></li><li><p>Меншік құқығының үш негізгі өкілеттігін түсіндіріңіз.</p></li><li><p>Жеке меншік пен мемлекеттік меншіктің айырмашылығы неде?</p></li><li><p>Ортақ меншік дегеніміз не және оның түрлері қандай?</p></li><li><p>Меншік құқығының объектілеріне не жатады?</p></li><li><p>Меншік құқығының пайда болу негіздерін атаңыз.</p></li><li><p>Меншік құқығын қорғаудың негізгі тәсілдері қандай?</p></li></ol>"},"14":{"title":"14-тақырып бойынша бақылау сұрақтары","filePath":"задание/14-лаб.docx","html":"<h3><strong>14-тақырып бойынша бақылау сұрақтары</strong> </h3><ol><li><p>Міндеттемелік құқық дегеніміз не?</p></li><li><p>Міндеттеменің негізгі мақсаты қандай?</p></li><li><p>Міндеттеменің тараптары кімдер?</p></li><li><p>Міндеттемелер қандай негіздерден туындайды?</p></li><li><p>Шарттан туындайтын міндеттемеге мысал келтіріңіз.</p></li><li><p>Міндеттеменің негізгі элементтерін атаңыз.</p></li><li><p>Міндеттемені тиісінше орындау дегеніміз не?</p></li><li><p>Міндеттемелерді қамтамасыз ету тәсілдері қандай?</p></li><li><p>Міндеттемені бұзғаны үшін қандай жауапкершілік қарастырылған?</p></li><li><p>Міндеттемелер қандай жағдайларда тоқтатылады?</p></li></ol>"},"15":{"title":"15-тақырып бойынша бақылау сұрақтары","filePath":"задание/15-лаб.docx","html":"<h3><strong>15-тақырып бойынша бақылау сұрақтары</strong></h3><ol><li><p>Шарт дегеніміз не?</p></li><li><p>Шарттың азаматтық құқықтағы маңызы қандай?</p></li><li><p>Шарт еркіндігі қағидасының мазмұнын түсіндіріңіз.</p></li><li><p>Шарттың негізгі белгілерін атаңыз.</p></li><li><p>Шарт талаптарының қандай түрлері бар?</p></li><li><p>Маңызды талаптарға не жатады?</p></li><li><p>Жария шарт пен қосылу шартының айырмашылығы неде?</p></li><li><p>Шарт қалай жасалады?</p></li><li><p>Шартты өзгерту және бұзу тәртібі қандай?</p></li><li><p>Шартты бұзғаны үшін қандай жауапкершілік көзделген?</p></li></ol>"}};
